define(["jquery"],function($){return{init:function(config){if(!config||!config.url||$("#local-missingstudents-course-button").length){return}var $button=$("<a>",{id:"local-missingstudents-course-button",href:config.url,class:"btn btn-outline-primary local-missingstudents-course-button",text:config.label});var $header=$("#page-header");var $target=$header.find(".page-header-headings").first().parent();if(!$target.length){$target=$header.find(".d-flex").first()}if(!$target.length){$target=$(".secondary-navigation").first()}if(!$target.length){return}$button.appendTo($target)}}});